    }
  } else if op == "-" {
    return left - right
  } else if op == "*" {
    return left * right
  } else if op == "/" {
    return left / right
  } else if op == "%" {
    return left % right
  } else if op == "==" {
    return left == right
  } else if op == "!=" {
    return left != right
  } else if op == "<" {
    return left < right
  } else if op == ">" {
    return left > right
  } else if op == "<=" {
    return left <= right
  } else if op == ">=" {
    return left >= right
  } else if op == "&&" or op == "and" {
    return left and right
  } else if op == "||" or op == "or" {
    return left or right
  } else {
    return null
